#include <bits/stdc++.h>using namespace std;#define int long longint T,n; void O_o(){    cin >> n;    map<int,int> mp;    for(int i=1;i<=n;i++){        for(int j=1;j<=n;j++){            int tmp;cin >> tmp;            mp[tmp]++;        }    }    int mx = -1;    for(auto &[a,b] : mp){        mx = max(mx,b);    }    if(mx > n * n - n){        cout << "No" << '\n';    }else{        cout << "Yes" << '\n';    }} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> T;    while(T--)O_o();    return 0;}